class Solution {
public:
    int minimumChanges(string s, int k) {
        const int n = s.size();
        const int INF = 1e9;
        // cost[i][j]: min changes to make s[i..j] a semi‑palindrome
        vector<vector<int>> cost(n, vector<int>(n, INF));

        // pre‑compute divisors for each possible length
        vector<vector<int>> divisors(n + 1);
        for (int len = 2; len <= n; ++len) {
            for (int d = 1; d * d <= len; ++d) {
                if (len % d == 0) {
                    if (d < len) divisors[len].push_back(d);
                    int d2 = len / d;
                    if (d2 != d && d2 < len) divisors[len].push_back(d2);
                }
            }
        }

        // compute cost for every interval
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) { // length at least 2
                int L = j - i + 1;
                int best = INF;
                for (int d : divisors[L]) {
                    int changes = 0;
                    for (int offset = 0; offset < d; ++offset) {
                        // collect positions of this residue class
                        vector<int> idx;
                        for (int p = i + offset; p <= j; p += d) idx.push_back(p);
                        int m = idx.size();
                        for (int t = 0; t < m / 2; ++t) {
                            if (s[idx[t]] != s[idx[m - 1 - t]]) ++changes;
                        }
                    }
                    best = min(best, changes);
                }
                cost[i][j] = best;
            }
        }

        // dp[pos][parts] = minimal changes for suffix starting at pos with parts left
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, INF));
        dp[n][0] = 0;
        for (int pos = n - 1; pos >= 0; --pos) {
            for (int parts = 1; parts <= k; ++parts) {
                // need at least 2*parts characters remaining
                if (n - pos < 2 * parts) continue;
                for (int end = pos + 1; end < n; ++end) { // interval length >=2
                    int len = end - pos + 1;
                    if (len < 2) continue;
                    if (n - (end + 1) < 2 * (parts - 1)) continue; // not enough left
                    if (cost[pos][end] == INF) continue; // should not happen
                    dp[pos][parts] = min(dp[pos][parts],
                                         cost[pos][end] + dp[end + 1][parts - 1]);
                }
            }
        }
        return dp[0][k];
    }
};
